#!/usr/bin/env node
// Extract the initial memory image of an ELF binary as 32-bit little/big-endian
// words keyed by virtual address. Only sections that are actually loaded into
// memory (SHF_ALLOC) and have file contents (not SHT_NOBITS) are included.
'use strict';
const fs = require('fs');

const SHT_NOBITS = 8;
const SHF_ALLOC = 0x2;

function main() {
  const file = process.argv[2];
  if (!file) {
    console.error('usage: node extract.js <elf-file>');
    process.exit(1);
  }
  const buf = fs.readFileSync(file);
  if (buf.length < 16 || buf.readUInt32BE(0) !== 0x7f454c46) {
    console.error('not an ELF file');
    process.exit(1);
  }
  const is64 = buf[4] === 2;
  const le = buf[5] !== 2;

  const u16 = (o) => (le ? buf.readUInt16LE(o) : buf.readUInt16BE(o));
  const u32 = (o) => (le ? buf.readUInt32LE(o) : buf.readUInt32BE(o));
  const uaddr = (o) =>
    is64 ? Number(le ? buf.readBigUInt64LE(o) : buf.readBigUInt64BE(o)) : u32(o);

  const shoff = is64 ? uaddr(0x28) : u32(0x20);
  const shentsize = u16(is64 ? 0x3a : 0x2e);
  const shnum = u16(is64 ? 0x3c : 0x30);

  const memory = {};
  for (let i = 0; i < shnum; i++) {
    const base = shoff + i * shentsize;
    if (base + shentsize > buf.length) break;
    const type = u32(base + 4);
    const flags = is64 ? uaddr(base + 8) : u32(base + 8);
    const addr = is64 ? uaddr(base + 0x10) : u32(base + 0x0c);
    const offset = is64 ? uaddr(base + 0x18) : u32(base + 0x10);
    const size = is64 ? uaddr(base + 0x20) : u32(base + 0x14);

    if (!(flags & SHF_ALLOC)) continue;
    if (type === SHT_NOBITS) continue;
    if (size === 0) continue;

    for (let j = 0; j + 4 <= size; j += 4) {
      const off = offset + j;
      if (off + 4 > buf.length) break;
      memory[addr + j] = u32(off);
    }
  }

  process.stdout.write(JSON.stringify(memory) + '\n');
}

main();

